import React, { useMemo, useState } from 'react';
import { useTranslation } from 'react-i18next';
import { Ban, Crown, Mail, Phone, Search, ShieldCheck, UserCheck, Users } from 'lucide-react';
import { useAdmin } from '../lib/store';
import { Avatar, Badge, Drawer, EmptyState, PageHeader, Progress, StatCard, cn } from '../lib/ui';
import { formatUZS, type Customer } from '../lib/mock';

export const Customers = () => {
  const { t } = useTranslation();
  const { customers, orders, toggleCustomerBlock, notify } = useAdmin();
  const [query, setQuery] = useState('');
  const [filter, setFilter] = useState('all');
  const [selected, setSelected] = useState<Customer | null>(null);

  const filtered = useMemo(() => {
    let list = [...customers];
    const q = query.trim().toLowerCase();
    if (q) list = list.filter((c) => `${c.name} ${c.phone} ${c.email}`.toLowerCase().includes(q));
    if (filter === 'vip') list = list.filter((c) => c.vip);
    if (filter === 'blocked') list = list.filter((c) => c.blocked);
    if (filter === 'new') list = list.filter((c) => c.joined >= '2025-01-01');
    return list;
  }, [customers, query, filter]);

  const totalSpent = customers.reduce((s, c) => s + c.spent, 0);
  const vipCount = customers.filter((c) => c.vip).length;
  const newCount = customers.filter((c) => c.joined >= '2025-01-01').length;

  const toggleBlock = (customer: Customer) => {
    toggleCustomerBlock(customer.id);
    setSelected({ ...customer, blocked: !customer.blocked });
    notify(customer.blocked ? t('unblock') : t('block'));
  };

  return (
    <div className="animate-fade-up">
      <PageHeader title={t('customersTitle')} subtitle={t('customersSubtitle')} />

      <div className="mb-5 grid grid-cols-1 gap-4 sm:grid-cols-2 xl:grid-cols-4">
        <StatCard label={t('totalCustomers')} value={String(customers.length)} icon={<Users size={20} />} />
        <StatCard label={t('vip')} value={String(vipCount)} icon={<Crown size={20} />} tone="amber" />
        <StatCard label={t('newThisMonth')} value={String(newCount)} icon={<UserCheck size={20} />} tone="sky" />
        <StatCard label="Umumiy xarid" value={formatUZS(totalSpent)} icon={<ShieldCheck size={20} />} tone="violet" />
      </div>

      <div className="card p-4 sm:p-5">
        <div className="mb-4 flex flex-col gap-2 sm:flex-row">
          <div className="relative flex-1">
            <Search size={17} className="absolute left-3.5 top-1/2 -translate-y-1/2 text-[var(--muted)]" />
            <input className="input pl-10" placeholder="Ism, telefon yoki email..." value={query} onChange={(e) => setQuery(e.target.value)} />
          </div>
          <select className="select sm:w-48" value={filter} onChange={(e) => setFilter(e.target.value)}>
            <option value="all">{t('all')}</option>
            <option value="vip">{t('vip')}</option>
            <option value="new">{t('newThisMonth')}</option>
            <option value="blocked">Bloklangan</option>
          </select>
        </div>

        {filtered.length === 0 ? (
          <EmptyState title={t('noData')} />
        ) : (
          <div className="table-wrap">
            <table className="data-table">
              <thead>
                <tr>
                  <th>{t('customer')}</th>
                  <th>{t('phone')}</th>
                  <th>{t('ordersCountLabel')}</th>
                  <th>{t('spent')}</th>
                  <th>{t('joined')}</th>
                  <th>{t('status')}</th>
                  <th className="text-right">{t('actions')}</th>
                </tr>
              </thead>
              <tbody>
                {filtered.map((c) => (
                  <tr key={c.id} className={cn(c.blocked && 'opacity-70')}>
                    <td>
                      <div className="flex items-center gap-3">
                        <Avatar emoji={c.emoji} size="md" />
                        <div>
                          <p className="flex items-center gap-1.5 text-xs font-extrabold">
                            {c.name}
                            {c.vip && <Crown size={12} className="text-amber-500" />}
                          </p>
                          <p className="text-[10px] text-[var(--muted)]">{c.email}</p>
                        </div>
                      </div>
                    </td>
                    <td className="text-xs font-semibold">{c.phone}</td>
                    <td className="text-xs font-extrabold">{c.orders}</td>
                    <td className="text-xs font-extrabold">{formatUZS(c.spent)}</td>
                    <td className="text-xs text-[var(--muted)]">{c.joined}</td>
                    <td>
                      {c.blocked ? <Badge tone="danger">Bloklangan</Badge> : c.vip ? <Badge tone="warning">{t('vip')}</Badge> : <Badge tone="success">{t('active')}</Badge>}
                    </td>
                    <td>
                      <div className="flex justify-end gap-1">
                        <button className="btn-secondary btn-sm" onClick={() => setSelected(c)}>{t('details')}</button>
                        <button
                          className={cn('icon-btn h-8 w-8', c.blocked ? 'text-brand-500' : 'text-rose-500')}
                          onClick={() => toggleBlock(c)}
                          title={c.blocked ? t('unblock') : t('block')}
                        >
                          {c.blocked ? <ShieldCheck size={14} /> : <Ban size={14} />}
                        </button>
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>

      <Drawer open={!!selected} onClose={() => setSelected(null)} title={t('customer')}>
        {selected && (
          <div className="space-y-5">
            <div className="flex flex-col items-center rounded-2xl bg-[var(--surface-2)] p-5 text-center">
              <Avatar emoji={selected.emoji} size="lg" />
              <h3 className="mt-2 font-display text-lg font-extrabold">{selected.name}</h3>
              <p className="text-xs text-[var(--muted)]">{selected.email}</p>
              <div className="mt-2 flex gap-1.5">
                {selected.vip && <Badge tone="warning"><Crown size={11} /> {t('vip')}</Badge>}
                <Badge tone={selected.blocked ? 'danger' : 'success'}>{selected.blocked ? 'Bloklangan' : t('active')}</Badge>
              </div>
              <div className="mt-4 grid w-full grid-cols-3 gap-2">
                <div className="card p-2"><p className="font-display text-base font-extrabold">{selected.orders}</p><p className="text-[9px] font-bold text-[var(--muted)]">{t('ordersCountLabel')}</p></div>
                <div className="card p-2"><p className="font-display text-sm font-extrabold">{formatUZS(selected.spent).replace(" so'm", '')}</p><p className="text-[9px] font-bold text-[var(--muted)]">so'm</p></div>
                <div className="card p-2"><p className="font-display text-base font-extrabold">4.9</p><p className="text-[9px] font-bold text-[var(--muted)]">Reyting</p></div>
              </div>
            </div>

            <div className="grid grid-cols-1 gap-2 sm:grid-cols-2">
              <a href={`tel:${selected.phone.replace(/\s/g, '')}`} className="btn-secondary"><Phone size={14} /> {selected.phone}</a>
              <a href={`mailto:${selected.email}`} className="btn-secondary"><Mail size={14} /> Email</a>
            </div>

            <div>
              <p className="mb-2 text-[10px] font-extrabold uppercase tracking-wider text-[var(--muted)]">Xarid tarixi</p>
              <div className="space-y-2">
                {orders.filter((o) => o.customerId === selected.id).slice(0, 5).map((o) => (
                  <div key={o.id} className="flex items-center gap-2 rounded-xl border p-2.5" style={{ borderColor: 'var(--border)' }}>
                    <div className="flex -space-x-1.5">
                      {o.items.slice(0, 2).map((it, i) => (
                        <span key={i} className="flex h-7 w-7 items-center justify-center rounded-lg bg-[var(--surface-3)] text-xs ring-2 ring-[var(--surface)]">{it.emoji}</span>
                      ))}
                    </div>
                    <div className="min-w-0 flex-1">
                      <p className="text-[11px] font-bold">#{o.id}</p>
                      <p className="text-[10px] text-[var(--muted)]">{o.createdAt.slice(0, 10)}</p>
                    </div>
                    <p className="text-[11px] font-extrabold">{formatUZS(o.total)}</p>
                  </div>
                ))}
                {orders.filter((o) => o.customerId === selected.id).length === 0 && (
                  <p className="rounded-xl bg-[var(--surface-2)] p-3 text-center text-xs text-[var(--muted)]">Buyurtmalar topilmadi</p>
                )}
              </div>
            </div>

            <div>
              <div className="mb-1.5 flex justify-between text-[10px] font-bold text-[var(--muted)]">
                <span>VIP darajaga yaqinlik</span>
                <span>{Math.min(100, Math.round((selected.spent / 3000000) * 100))}%</span>
              </div>
              <Progress value={Math.min(100, (selected.spent / 3000000) * 100)} tone="amber" />
            </div>

            <button className={cn('btn w-full', selected.blocked ? 'bg-brand-600 text-white' : 'bg-rose-500 text-white hover:bg-rose-600')} onClick={() => toggleBlock(selected)}>
              {selected.blocked ? <ShieldCheck size={15} /> : <Ban size={15} />} {selected.blocked ? t('unblock') : t('block')}
            </button>
          </div>
        )}
      </Drawer>
    </div>
  );
};
